# Survivors mid-toss: held at the window during the grab, flung straight up, then dropped
# into the bag on his back (which moves with him). Small code-drawn figures, spinning.
func _draw_flights() -> void:
	var ink := Color("25354a")
	for fl in flights:
		var t: int = fl.t
		var from: Vector2 = fl.from + Vector2(0.0, -12.0)
		var launch: Vector2 = fl.get("launch", from)
		var apex: Vector2 = fl.get("apex", from + Vector2(0.0, -TOSS_HEIGHT))
		var bag: Vector2 = Player.BAG.get(player.pose, Player.BAG.idle)
		var into := player.position + Vector2(bag.x * player.facing, bag.y - 6.0)
		var pos := from
		var spin := 0.0
		if t >= GRAB_TICKS + TOSS_UP_TICKS:
			var k := float(t - GRAB_TICKS - TOSS_UP_TICKS) / float(TOSS_DOWN_TICKS)
			pos = Vector2(lerpf(apex.x, into.x, k), lerpf(apex.y, into.y, k * k))
			spin = float(t) * 0.5
		elif t >= GRAB_TICKS:
			var k := float(t - GRAB_TICKS) / float(TOSS_UP_TICKS)
			pos = launch.lerp(apex, 1.0 - (1.0 - k) * (1.0 - k))
			spin = float(t) * 0.5
		draw_set_transform(pos, spin, Vector2.ONE)
		if fl.type == "dog":
			draw_rect(Rect2(-7, -3, 12, 7), ink)
			draw_rect(Rect2(-6, -2, 10, 5), Color("d59243"))
			draw_circle(Vector2(6, -3), 4.0, ink)
			draw_circle(Vector2(6, -3), 3.0, Color("d59243"))
		else:
			draw_rect(Rect2(-4, -2, 8, 10), ink)
			draw_rect(Rect2(-3, -1, 6, 8), Color("46a0e0"))
			draw_circle(Vector2(0, -6), 4.5, ink)
			draw_circle(Vector2(0, -6), 3.5, Color("f2c9a0"))
		draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)

# World text: light or colored fill with a dark outline, readable on ENV-BG and on the buildings.
func _label(pos: Vector2, text: String, size: int, color: Color) -> void:
	var font := ThemeDB.fallback_font
	draw_string_outline(font, pos, text, HORIZONTAL_ALIGNMENT_LEFT, -1, size, 4, Color(0.106, 0.133, 0.188, color.a))
	draw_string(font, pos, text, HORIZONTAL_ALIGNMENT_LEFT, -1, size, color)

# Two buses so music and effects mute separately (N / B). Streams load only if the file exists,
# so a missing sound leaves the game unchanged.
func _setup_audio() -> void:
	for bus in ["Music", "SFX"]:
		if AudioServer.get_bus_index(bus) == -1:
			AudioServer.add_bus()
			AudioServer.set_bus_name(AudioServer.bus_count - 1, bus)
	for id in SFX_FILES:
		var p := AudioStreamPlayer.new()
		p.bus = "SFX"
		var path := "res://audio/%s.ogg" % SFX_FILES[id]
		if ResourceLoader.exists(path):
			p.stream = load(path)
		add_child(p)
		sfx_players[id] = p
		sfx_counts[id] = 0
	music = AudioStreamPlayer.new()
	music.bus = "Music"
	if ResourceLoader.exists(MUSIC_FILE):
		music.stream = load(MUSIC_FILE)
		music.stream.loop = true
	add_child(music)

func play_sfx(id: String) -> void:
	sfx_counts[id] += 1
	sfx_log.append({"id": id, "state": state, "tick": player.tick})
	var p: AudioStreamPlayer = sfx_players[id]
	if p.stream:
		p.play()

func _toggle_mute(bus: String) -> void:
	var i := AudioServer.get_bus_index(bus)
	AudioServer.set_bus_mute(i, not AudioServer.is_bus_mute(i))

func is_muted(bus: String) -> bool:
	return AudioServer.is_bus_mute(AudioServer.get_bus_index(bus))

# Music follows the state (CHANGE-BRIEF "Music behavior"): plays while playing, pauses in place on
# pause, dips under the burn while DYING and comes back on retry (no restart), stops on COMPLETE,
# off in the menu.
func _process(_delta: float) -> void:
	if music == null or music.stream == null:
		return
	match state:
		State.PLAYING:
			music.volume_db = 0.0
			music.stream_paused = false
			if not music.playing:
				music.play()
		State.DYING:
			music.volume_db = MUSIC_DIP_DB
		State.PAUSED:
			music.stream_paused = true
		_:
			music.stop()

extends SceneTree
# A5 controlled-value captures (CHANGE-BRIEF A4, TEST-REPORT "Controlled values"). Needs a window:
#   ~/Downloads/Godot.app/Contents/MacOS/Godot --path godot --script res://tests/capture_glow.gd
# Starts a real session, walks Extinguisho into hose range, presses W through Input so the hose
# pose and water are real, then for each controlled glow value: stops the driver's _process so it
# cannot overwrite the value, sets the uniform from code, waits for the frame to draw, saves the
# rendered viewport as PNG, and samples the three named texels P1-P3 (and the glow-2.0 clamp case).
# It is real engine output, not a headless log. Judging the captures is the human check.
const Game = preload("res://game/session.gd")
var OUT: String = ProjectSettings.globalize_path("res://").path_join("../a5/evidence/captures/")
const VALUES := [0.0, 0.5, 1.0, 2.0]
# Named texels in hose.png (CHANGE-BRIEF A4) and their file colours.
const PIXELS := {"P1": Vector2i(77, 49), "P2": Vector2i(51, 26), "P3": Vector2i(63, 6)}
var game: Node2D

func _initialize() -> void:
	call_deferred("run")

func steps(n: int) -> void:
	for i in range(n):
		await physics_frame
		await process_frame

func key(code: Key, pressed: bool) -> void:
	var e := InputEventKey.new()
	e.keycode = code
	e.physical_keycode = code
	e.pressed = pressed
	Input.parse_input_event(e)

func run() -> void:
	DirAccess.make_dir_recursive_absolute(OUT)
	game = Game.new()
	game.test_mode = true
	root.add_child(game)
	game.start_session()
	game.player.position = Vector2(1220, 240)  # hose range, same spot as the tests
	game.player.facing = 1.0
	await steps(3)
	key(KEY_W, true)
	await steps(2)
	key(KEY_W, false)
	# Wait for the real hose pose: hosing true AND the 30-tick respawn stance over, so the sprite is
	# hose.png and its anchor is the one the A4 texel mapping assumes. Then let the camera settle.
	var guard := 0
	while guard < 200 and not (game.player.hosing and game.player.pose == "hose"):
		await steps(1)
		guard += 1
	if not (game.player.hosing and game.player.pose == "hose"):
		push_error("hose pose never showed (hosing=%s pose=%s); nothing captured" % [game.player.hosing, game.player.pose])
		quit(1)
		return
	await steps(5)
	var player: CharacterBody2D = game.player
	var sprite: Sprite2D = player.sprite
	var driver: Node = player.get_node("HoseGlow")
	var mat: ShaderMaterial = sprite.material
	print("pose=%s facing=%d player=%s window=%s" % [player.pose, int(player.facing), player.position, get_root().size])
	# `-- bag`: CHANGE-BRIEF F5. Rescues happen after the hose in this level, so the bag with a survivor
	# in it is never on screen while he glows in normal play. For the controlled capture only, put a
	# rescued person in the bag (a test fixture on the player, the same fields the session sets), so
	# the code-drawn bag can be sampled next to the glowing sprite: it must stay orange (230, 126, 34).
	var bag_mode := "bag" in OS.get_cmdline_user_args()
	if bag_mode:
		player.bag_types = ["person"]
		player.rescued = 1
		player.queue_redraw()
		await steps(2)
	# Freeze the driver (it writes glow every _process); the session keeps running so the water pours.
	driver.set_process(false)
	for v in VALUES:
		mat.set_shader_parameter("glow", v)
		await RenderingServer.frame_post_draw
		await RenderingServer.frame_post_draw
		var img: Image = get_root().get_texture().get_image()
		var path := OUT + ("bag_glow_%s.png" if bag_mode else "glow_%s.png") % String.num(v, 1)
		img.save_png(path)
		# canvas coords are the 640x360 game space; the final transform applies the canvas_items
		# stretch to the 1280x720 window the image was read from.
		var xf: Transform2D = get_root().get_final_transform() * sprite.get_global_transform_with_canvas()
		var row := {"glow": v, "uniform_readback": mat.get_shader_parameter("glow"), "file": path, "image": "%dx%d" % [img.get_width(), img.get_height()]}
		row["pose"] = player.pose
		row["sprite_origin_window_px"] = [xf.origin.x, xf.origin.y]
		for name in PIXELS:
			var t: Vector2i = PIXELS[name]
			var p: Vector2 = xf * Vector2(t.x + 0.5, t.y + 0.5)  # texel centre -> window pixel
			var pi := Vector2i(int(floor(p.x)), int(floor(p.y)))
			var c := img.get_pixel(pi.x, pi.y)
			var neigh := []  # the 3x3 around it, so a one-pixel misalignment is visible
			for dy in [-1, 0, 1]:
				for dx in [-1, 0, 1]:
					var n := img.get_pixel(pi.x + dx, pi.y + dy)
					neigh.append([n.r8, n.g8, n.b8])
			row[name] = {"texel": [t.x, t.y], "window_px": [pi.x, pi.y], "rgb": [c.r8, c.g8, c.b8], "neighbours_3x3": neigh}
		if bag_mode:
			# bag centre for the hose pose: player.gd BAG["hose"] = (-10, -19) game px, facing right
			var bag_world: Vector2 = player.get_global_transform_with_canvas() * Vector2(-10.0 * player.facing, -19.0)
			var bp: Vector2 = get_root().get_final_transform() * bag_world
			var bpi := Vector2i(int(floor(bp.x)), int(floor(bp.y)))
			var bc := img.get_pixel(bpi.x, bpi.y)
			row["bag"] = {"window_px": [bpi.x, bpi.y], "rgb": [bc.r8, bc.g8, bc.b8], "expected": [230, 126, 34]}
		print(JSON.stringify(row))
	driver.set_process(true)
	print("CAPTURE DONE: %d files in %s" % [VALUES.size(), OUT])
	quit(0)

## A3 headless check of the three props in scenes3d/props_room.tscn.
##   timeout 120 godot --headless --path godot --script res://tests/check_props.gd --fixed-fps 60
##   ... -- mutate     (deliberately breaks the scene in memory: the check must then FAIL all three props)
## For each prop it prints, beside my brief (latest CHANGE-BRIEF revision, in Godot axes W x H x D):
##   - the GLOBAL bounding box (every MeshInstance3D's AABB pushed through its global transform,
##     so a rotated or scaled node cannot hide behind a correct-looking mesh),
##   - the scale of the prop node and of every mesh node under it,
##   - which world axis the prop's height lies along (Y = upright),
##   - the bottom of the prop compared with the floor's surface (sits on it / floats / sinks),
##   - the triangle count from the imported index buffers, against my budget.
## What it does NOT show: whether the props look right, read as a hydrant / backpack / flame,
## have the right colours, or suit the game's style. Those are my human checks.
extends SceneTree

const TOL := 0.01  # metres
const PROPS := {
	"Hydrant":   {"brief": Vector3(0.40, 0.80, 0.36),  "budget": 400},
	"RescueBag": {"brief": Vector3(0.36, 0.612, 0.306), "budget": 300},
	"Flame":     {"brief": Vector3(0.36, 0.62, 0.265),  "budget": 400},
}

func _initialize() -> void:
	var scene: Node3D = load("res://scenes3d/props_room.tscn").instantiate()
	root.add_child(scene)
	var mutate := "mutate" in OS.get_cmdline_user_args()
	if mutate:
		# Planted faults: the check must catch every one of them.
		scene.get_node("Hydrant").rotate_z(PI / 2)            # lying on its side (prediction P1)
		scene.get_node("RescueBag").scale = Vector3(2, 2, 2)  # scale not 1 (wrong size)
		scene.get_node("Flame").position.y -= 0.2             # sunk into the floor (prediction P2)
		print("MUTATE MODE: hydrant rotated 90 deg, bag scaled x2, flame lowered 0.2 m")
	await process_frame

	var floor: MeshInstance3D = scene.get_node("Floor")
	var floor_y: float = _global_aabb(floor).end.y   # the top of the floor plane (a flat plane: its top IS its surface)
	print("Floor surface at y = %.4f (plane %s, its own scale %s)" % [floor_y, floor.mesh.size, floor.scale])

	var failures := 0
	for name in PROPS:
		var node: Node3D = scene.get_node(name)
		var spec: Dictionary = PROPS[name]
		var brief: Vector3 = spec.brief
		var budget: int = spec.budget
		var box := _global_aabb(node)
		var size := box.size
		var scales: Array = [node.scale]
		var tris := 0
		for mi in _meshes(node):
			scales.append(mi.global_transform.basis.get_scale())
			tris += _triangles(mi.mesh)
		var all_one: bool = scales.all(func(s): return s.is_equal_approx(Vector3.ONE))
		var tallest: String = "X" if size.x >= size.y and size.x >= size.z else ("Y" if size.y >= size.z else "Z")
		var bottom_gap: float = box.position.y - floor_y
		var on_floor: bool = absf(bottom_gap) <= TOL
		var diff: Vector3 = (size - brief).abs()
		var size_ok: bool = diff.x <= TOL and diff.y <= TOL and diff.z <= TOL
		var upright: bool = tallest == "Y" and node.global_transform.basis.y.normalized().is_equal_approx(Vector3.UP)
		var ok: bool = size_ok and all_one and upright and on_floor and tris <= budget
		if not ok:
			failures += 1
		print("%-9s | size W×H×D %.3f × %.3f × %.3f m (brief %.3f × %.3f × %.3f) %s | scale %s | height along %s %s | bottom %+.4f m vs floor %s | tris %d / %d %s | %s" % [
			name, size.x, size.y, size.z, brief.x, brief.y, brief.z, "ok" if size_ok else "OFF",
			"1,1,1" if all_one else str(scales), tallest, "(upright)" if upright else "(NOT upright)",
			bottom_gap, "on it" if on_floor else ("FLOATS" if bottom_gap > 0 else "SINKS"),
			tris, budget, "ok" if tris <= budget else "OVER", "PASS" if ok else "FAIL"])
	print("RESULT: %s (%d of %d props failing)%s" % ["PASS" if failures == 0 else "FAIL", failures, PROPS.size(), " [mutate mode]" if mutate else ""])
	quit(1 if failures > 0 else 0)

func _meshes(n: Node) -> Array:
	var out: Array = []
	if n is MeshInstance3D:
		out.append(n)
	for c in n.get_children():
		out.append_array(_meshes(c))
	return out

func _global_aabb(n: Node) -> AABB:
	var box := AABB()
	var first := true
	for mi in _meshes(n):
		var a: AABB = mi.mesh.get_aabb()
		for i in 8:
			var p: Vector3 = mi.global_transform * a.get_endpoint(i)
			if first:
				box = AABB(p, Vector3.ZERO)
				first = false
			else:
				box = box.expand(p)
	return box

func _triangles(mesh: Mesh) -> int:
	var t := 0
	for s in mesh.get_surface_count():
		var arrays: Array = mesh.surface_get_arrays(s)
		var idx = arrays[Mesh.ARRAY_INDEX]
		t += (idx.size() if idx != null else arrays[Mesh.ARRAY_VERTEX].size()) / 3
	return t

extends Control
var game: Node2D
const INK := Color("25354a")
# CHAR-EXPR-02's DEVASTATED portrait (generated), shown big when the fire gets him: at 64 px the
# burned pose can't show his face, so the punchline gets a comic close-up (storyboard panel 4). Visual only.
const PORTRAIT := preload("res://art/character/devastated_portrait.png")
# The bow close-up (from pose 12b), shown the same way when the level is complete (playtest 3).
const WIN_PORTRAIT := preload("res://art/character/celebrate_portrait.png")

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)

func text_at(text: String, position: Vector2, size_px: int = 14, color: Color = INK) -> void:
	draw_string(ThemeDB.fallback_font, position, text, HORIZONTAL_ALIGNMENT_LEFT, -1, size_px, color)

func centered(text: String, y: float, font_size: int, color: Color = INK) -> void:
	var width := ThemeDB.fallback_font.get_string_size(text, HORIZONTAL_ALIGNMENT_LEFT, -1, font_size).x
	text_at(text, Vector2((640-width)/2, y), font_size, color)

func _draw() -> void:
	if not is_instance_valid(game):
		return
	draw_rect(Rect2(0,0,640,74), Color("f6f3ec"))
	text_at("FIREFIGHTER RESCUE", Vector2(22,27), 18)
	text_at("FIRST ALARM", Vector2(510,27), 14)
	text_at("A/D or arrows: move   Space: jump   W: hose   R: retry   Esc: pause   N/B: mute music/sound", Vector2(22,50), 12)
	var mutes := ("MUSIC OFF  " if game.is_muted("Music") else "") + ("SOUND OFF" if game.is_muted("SFX") else "")
	if mutes != "":
		text_at(mutes, Vector2(330,27), 11, Color("a23e36"))  # between the title and FIRST ALARM (was 470: overlapped it)
	draw_rect(Rect2(22,63,596,3), Color("daddd6"))
	var progress: float = clampf((game.player.position.x-64)/maxf(1.0, float(game.level.finish[0])-64.0), 0, 1)
	draw_rect(Rect2(22,63,596*progress,3), Color("287c68"))
	draw_rect(Rect2(0,335,640,25), Color("f6f3ec"))
	text_at("No lives. Just get them out.", Vector2(22,353), 13)
	var remaining: float = maxf(0.0, float(game.level.time_limit) - game.elapsed)
	var tcol := Color("a23e36") if remaining < 10.0 else INK
	text_at("RETRIES %02d     TIME %04.1fs" % [game.deaths, remaining], Vector2(428,353), 13, tcol)
	text_at("SAVE:", Vector2(206,353), 12)
	var ox := 246.0
	for s in game.survivors:
		text_at(("[x] " if s.rescued else "[ ] ") + ("DOG" if s.type == "dog" else "PERSON"), Vector2(ox,353), 12, Color("287c68") if s.rescued else INK)
		ox += 84.0
	if game.state == game.State.PLAYING:
		return
	if game.state == game.State.DYING:
		draw_rect(Rect2(180,128,280,68), Color("fff9ee"))
		centered(game.death_reason, 155, 21, Color("a23e36"))
		centered("Back at the start in a moment.", 180, 13)
		if game.death_reason == "The fire got you.":
			pop_portrait(PORTRAIT, game.FIRE_DEATH_HOLD - game.retry_remaining, -0.06)
		return
	if game.state == game.State.COMPLETE:
		pop_portrait(WIN_PORTRAIT, game.complete_ticks / 60.0, 0.06)
		if game.complete_ticks < game.BOW_TICKS:
			return  # let the player see the bow first (storyboard panel 6)
