extends SceneTree
# Throwaway smoke run (deleted after use): loads the preview headless in both modes for 60 frames
# and prints what is in the tree. No pixels.
func _initialize() -> void:
	call_deferred("run")

func run() -> void:
	for mode in [false, true]:
		var p: Node2D = load("res://previews/jump_puff_preview.tscn").instantiate()
		p.retrigger = mode
		root.add_child(p)
		var game: Node2D = p.get_node("WalkerJumpman")
		print("mode retrigger=%s camera=%s hud_visible=%s state=%d player=%s" % [mode, game.camera.position, game.hud.visible, game.state, game.player.position])
		for f in range(60):
			await process_frame
			var puffs := []
			for c in game.get_children():
				if c.name.begins_with("JumpPuff") or c.scene_file_path == "res://effects/jump_puff.tscn":
					puffs.append("%s@%s flash=%s puff=%s specks=%s" % [c.name, c.position, c.get_node("Flash").emitting, c.get_node("Puff").emitting, c.get_node("Specks").emitting])
			if f in [9, 10, 11, 13, 24, 25, 26, 40, 59]:
				print("  after frame %d: preview.frame=%d puffs=%s" % [f, p.frame, puffs])
		p.queue_free()
		await process_frame
	quit(0)

